@Composable
fun LocalizedText(
    text: String,
    modifier: Modifier = Modifier,
    color: Color = Color.Unspecified,
    fontSize: TextUnit = TextUnit.Unspecified,
    fontStyle: FontStyle? = null,
    fontWeight: FontWeight? = null,
    fontFamily: FontFamily? = null,
    letterSpacing: TextUnit = TextUnit.Unspecified,
    textDecoration: TextDecoration? = null,
    textAlign: TextAlign? = null,
    lineHeight: TextUnit = TextUnit.Unspecified,
    overflow: TextOverflow = TextOverflow.Clip,
    softWrap: Boolean = true,
    maxLines: Int = Int.MAX_VALUE,
    minLines: Int = 1,
    onTextLayout: (TextLayoutResult) -> Unit = {},
    style: TextStyle = LocalTextStyle.current
) {
    val language = LocalAppLanguage.current
    // Some strings include live values (for example a date or rate), so they are handled as prefixes below.
    // Exact translations are looked up by their English source text; unknown text safely stays readable in English.
    val translated = when {
        text == "Other" && language == "de" -> "Sonstiges"
        text == "Other" && language == "es" -> "Otros"
        text == "Other" && language == "fr" -> "Autre"
        text == "Other" && language == "pt" -> "Outro"
        text == "Other" && language == "it" -> "Altro"
        text == "Other" && language == "nl" -> "Overig"
        text == "Other" && language == "pl" -> "Inne"
        text == "Other" && language == "th" -> "อื่น ๆ"
        text == "Other" && language == "ko" -> "기타"
        language == "de" && text.startsWith("Currencies (") -> text.replace("Currencies (", "Währungen (")
        language == "de" && text.startsWith("Custom and fan currencies (") -> text.replace("Custom and fan currencies (", "Eigene Währungen und Fan-Währungen (")
        language == "es" && text.startsWith("Currencies (") -> text.replace("Currencies (", "Monedas (")
        language == "es" && text.startsWith("Custom and fan currencies (") -> text.replace("Custom and fan currencies (", "Monedas personalizadas y de fans (")
        language == "de" && text.startsWith("Last rate update: ") -> text.replace("Last rate update: ", "Letzte Kursaktualisierung: ")
        language == "de" && text.startsWith("Offline – last update: ") -> text.replace("Offline – last update: ", "Offline – letzte Aktualisierung: ")
        language == "de" && text.startsWith("Updating rates … (as of ") -> text.replace("Updating rates … (as of ", "Kurse werden aktualisiert … (Stand: ")
        language == "es" && text.startsWith("Last rate update: ") -> text.replace("Last rate update: ", "Última actualización del tipo: ")
        language == "es" && text.startsWith("Offline – last update: ") -> text.replace("Offline – last update: ", "Sin conexión – última actualización: ")
        language == "es" && text.startsWith("Updating rates … (as of ") -> text.replace("Updating rates … (as of ", "Actualizando tipos … (a fecha de ")
        language == "de" && text.startsWith("Exchange rate (") -> text.replace("Exchange rate (", "Wechselkurs (")
        language == "es" && text.startsWith("Exchange rate (") -> text.replace("Exchange rate (", "Tipo de cambio (")
        language == "zh" && text.startsWith("Exchange rate (") -> text.replace("Exchange rate (", "汇率（")
        language == "ja" && text.startsWith("Exchange rate (") -> text.replace("Exchange rate (", "為替レート（")
        language == "de" && text.startsWith("From ") -> text.replaceFirst("From ", "Aus ")
        language == "es" && text.startsWith("From ") -> text.replaceFirst("From ", "De ")
        language == "zh" && text.startsWith("From ") -> text.replaceFirst("From ", "来自 ")
        language == "ja" && text.startsWith("From ") -> text.replaceFirst("From ", "出典：")
        language == "de" && text.contains(" increase over ") -> text.replace(" increase over ", " Anstieg im Zeitraum ").replace("day", "Tag").replace("week", "Woche").replace("month", "Monat").replace("year", "Jahr")
        language == "de" && text.contains(" decrease over ") -> text.replace(" decrease over ", " Rückgang im Zeitraum ").replace("day", "Tag").replace("week", "Woche").replace("month", "Monat").replace("year", "Jahr")
        language == "es" && text.contains(" increase over ") -> text.replace(" increase over ", " aumento en ").replace("day", "día").replace("week", "semana").replace("month", "mes").replace("year", "año")
        language == "es" && text.contains(" decrease over ") -> text.replace(" decrease over ", " descenso en ").replace("day", "día").replace("week", "semana").replace("month", "mes").replace("year", "año")
        (language == "zh" || language == "ja") && text.contains(" increase over ") -> text.replace(" increase over ", if (language == "zh") "上涨（" else "上昇（").replace("day", "日").replace("week", if (language == "zh") "周" else "週間").replace("month", if (language == "zh") "个月" else "か月").replace("year", "年") + if (language == "zh") "）" else "）"
        (language == "zh" || language == "ja") && text.contains(" decrease over ") -> text.replace(" decrease over ", if (language == "zh") "下跌（" else "下落（").replace("day", "日").replace("week", if (language == "zh") "周" else "週間").replace("month", if (language == "zh") "个月" else "か月").replace("year", "年") + "）"
        else -> moreLanguageTranslations[language]?.get(text)
            ?: additionalTranslations[language]?.get(text)
            ?: when (language) {
                "zh" -> chinese[text]
                "ja" -> japanese[text]
                "de" -> german[text]
                "es" -> spanish[text]
                else -> null
            } ?: text
    }
    MaterialText(
        text = translated, modifier = modifier, color = color, fontSize = fontSize, fontStyle = fontStyle,
        fontWeight = fontWeight, fontFamily = fontFamily, letterSpacing = letterSpacing,
        textDecoration = textDecoration, textAlign = textAlign, lineHeight = lineHeight,
        overflow = overflow, softWrap = softWrap, maxLines = maxLines, minLines = minLines,
        onTextLayout = onTextLayout, style = style
    )
}

@Composable
fun ProvideAppLanguage(language: String, content: @Composable () -> Unit) {
    CompositionLocalProvider(LocalAppLanguage provides language, content = content)
}
